from pathlib import Path
import json,html
r=Path(__file__).parent
d=json.loads((r/'crawl-results.json').read_text(encoding='utf8'));checks=json.loads((r/'document-checks.json').read_text(encoding='utf8'))
style='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#edf2f9;color:#1c2b44;font:16px/1.7 'Segoe UI',Arial,sans-serif}a{color:#245eb8}header{background:#0b1120;color:#e9eef8;padding:55px 0}header p{color:#a9bbd5;max-width:780px}h1,h2,h3{line-height:1.15;letter-spacing:-.03em}h1{font-size:clamp(35px,5vw,60px);margin:18px 0}h2{font-size:30px;margin-top:0}h3{font-size:21px}main,.inner{max-width:1120px;margin:auto;padding:0 30px}section{background:white;border:1px solid #d4dfed;border-radius:9px;padding:35px;margin:25px 0}nav{display:flex;gap:20px;flex-wrap:wrap;margin-top:27px}header a{color:#a9c7ff}.label{font-size:12px;letter-spacing:.12em;text-transform:uppercase}.intro{font-size:21px;line-height:1.6}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.card{border:1px solid #c8d7ec;border-radius:7px;padding:23px}.card img{width:100%;border-radius:4px}.card h3{margin:15px 0}.card p{font-size:14px}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;padding:13px 12px;vertical-align:top;border-bottom:1px solid #d9e2ee}th{background:#eef3fa}td:first-child{white-space:nowrap}.scroll{overflow:auto}.badge{display:inline-block;padding:3px 10px;border-radius:4px;font-size:12px;font-weight:700;background:#dbe8ff;color:#244f8c}.p0{background:#ffe1e0;color:#963333}.p1{background:#fff0cd;color:#78580c}.finding{border-left:4px solid #3f72bb;padding-left:22px;margin:30px 0 40px}.finding h3{margin:8px 0}.finding p{margin:10px 0}.finding .small{font-size:13px;color:#5e708a}code{font-size:13px;background:#edf2f9;padding:2px 5px;overflow-wrap:anywhere}blockquote{border-left:3px solid #7296d2;margin:20px 0;padding:10px 20px;background:#f1f5fb}img{max-width:100%}.note{background:#e8f0ff;border:1px solid #c0d2ef;padding:20px;border-radius:6px}li{margin-bottom:8px}.swatches{display:flex;gap:12px;flex-wrap:wrap}.swatch{padding:20px;color:white;border-radius:5px;font:13px monospace;min-width:125px}footer{max-width:1120px;margin:35px auto;padding:0 30px;color:#657791;font-size:13px}.btn{display:inline-block;background:#2f6be6;color:white;text-decoration:none;border-radius:5px;padding:10px 17px;margin:8px 8px 0 0}.compare{display:grid;grid-template-columns:1fr 1fr;gap:25px}.compare img{width:100%}@media(max-width:760px){main,.inner{padding:0 18px}section{padding:23px}.grid,.compare{grid-template-columns:1fr}h1{font-size:38px}td,th{min-width:150px}.swatch{min-width:100px}}@media print{header{background:white;color:black;padding:15px 0}header p,header a{color:#333}body{background:white}section{break-inside:avoid;border:0;padding:15px 0}nav,.btn{display:none}.grid{grid-template-columns:1fr 1fr}h1{font-size:32px}a{color:#222}main,.inner{padding:0}}
'''
def page(title,sub,body,file):
 nav='<nav><a href="index.html">Übersicht & Designs</a><a href="analysebericht.html">Analysebericht</a><a href="verbesserungsbericht.html">Verbesserungsbericht</a></nav>'
 (r/file).write_text('<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><style>'+style+'</style></head><body><header><div class="inner"><div class="label">SCUTORIA · WEBSITE-AUDIT · 01.11.2026</div><h1>'+title+'</h1><p>'+sub+'</p>'+nav+'</div></header><main>'+body+'</main><footer>Prüfstand 01.11.2026 · Öffentliche Website und eigene fiktive Testläufe · Keine Live-Änderungen. Die Entwürfe sind lokal und nicht veröffentlicht.</footer></body></html>',encoding='utf8')
findings=[
('P0','F01','Kaufweg im Test ohne sichtbare Reaktion','Bei beiden englischen Produktseiten blieb der Browser nach Klick auf den tatsächlichen Kaufbutton auf der Seite. Kein Stripe-Checkout und keine verständliche Fehlermeldung erschienen. Die Kauf-Endpunkte antworteten beim gesonderten POST-Test mit HTTP 303 zu checkout.stripe.com.','Produktseiten beider Toolkits; eigene Browser- und HTTP-Tests.','Ein echtes Funktionsproblem im geprüften In-App-Browser. Die Ursache ist noch nicht bewiesen. Der ausgelieferte CSP-Header enthält form-action \'self\'; das passt als mögliche Ursache zu einer blockierten externen Formularweiterleitung. Browserabhängigkeit gezielt gegenprüfen.','Kaufnavigation in normalem Chrome und Firefox reproduzieren; CSP-Verstoß und Netzwerkantwort erfassen. Nur das notwendige Checkout-Ziel zulassen oder einen geeigneten servergestützten Checkout-Link verwenden. Keine pauschale Abschaltung der Sicherheitsrichtlinie. Bei Fehlern sichtbare Meldung mit erneutem Versuch.','Beide Produkte in EN und DE erreichen Stripe im Zielbrowser. Preis, Laufzeit und Produkt stimmen überein. Abbruch führt sinnvoll zurück; Fehlersimulation zeigt eine verständliche Meldung.'),
('P0','F02','Verkaufsversprechen trifft auf öffentliche Entwürfe','Die Website zeigt Preview/Vorschau und zugleich Available now/Jetzt erhältlich, einen Preis und Kaufbuttons. Produktseiten weisen auf lizenzfreie Generatoren im Vorschaumodus hin. Die Datenschutzerklärung beginnt mit einem Entwurfsvermerk und enthält offene Angaben wie [90 days], [to be checked], Hosting-, Aufbewahrungs- und Vertragsplatzhalter.','Startseite, beide Produktseiten, /privacy und /de/datenschutz.','Der Betriebsstatus ist unklar. Das ist besonders bei einem Angebot für verlässliche Regeln und Nachweise ein starker Vertrauensbruch. Hier wird keine konkrete Rechtsverletzung festgestellt.','Verbindlich zwischen öffentlicher Testphase und Verkaufsbetrieb entscheiden. Für Testphase Zugang und Beispieldaten klar erklären und Verkaufsaktionen passend begrenzen. Vor Verkaufsfreigabe tatsächliche Datenflüsse und Vertragsgrundlagen klären und Rechtstexte prüfen lassen. Danach konsistente Statusanzeigen.','Ein klarer Status auf Startseite, Produktseiten, Generator und Kasse. Keine offenen redaktionellen Platzhalter in veröffentlichten Pflichtinformationen. Rechts- und Veröffentlichungsfreigabe durch Stefan.'),
('P1','F03','Mobile Hauptnavigation verschwindet','Bei 390 Pixel Breite sind Produkte, Tools und Konto im Header ausgeblendet. Ein Menüknopf oder ein gleichwertiger Ersatz fehlt. Die Startseite enthält einzelne Produkt- und Toollinks, aber keinen gleichwertigen mobilen Kontozugang.','Eigene DOM- und Sichtprüfung der deutschen Startseite; ist-mobil.jpg.','Besucher verlieren auf kleinen Bildschirmen Orientierung und wiederkehrende Kunden ihren direkten Einstieg.','Ein zugängliches mobiles Menü mit Produkte, kostenlose Tools, Handbücher und Konto einführen. Schließen, Escape, Fokusführung und aktiver Zustand berücksichtigen.','Alle Hauptziele sind bei schmalem Bildschirm mit Tastatur und Touch erreichbar. Keine horizontale Seitenverschiebung; der Kontozugang bleibt verfügbar.'),
('P1','F04','Suchmaschinen bleiben im Vorschaumodus','Alle 38 erfassten HTML-Seiten enthalten noindex, nofollow. robots.txt enthält User-agent: * und Disallow: /. Eine Sitemap ist trotzdem abrufbar.','Eigener Crawl: crawl-results.json; /robots.txt; /sitemap.xml.','Für eine Vorschau plausibel. Für den Verkaufsstart verhindert dies die reguläre Erschließung der Inhalte. robots.txt allein garantiert außerdem keine vollständige Entfernung einer URL aus Suchergebnissen.','Indexierungsregeln je Umgebung festlegen. Bei Verkaufsfreigabe öffentliche Marketingseiten gezielt freigeben, private Ergebnisse und Konto ausschließen. Sitemap und Canonicals prüfen; Search Console anschließend mit echter URL-Prüfung nutzen.','Öffentliche Zielseiten sind crawlbar und enthalten kein unbeabsichtigtes noindex. Private Seiten bleiben geschützt. Keine Aussage über Rankings ohne Messung.'),
('P1','F05','Quellen sind nicht direkt nachprüfbar verlinkt','In allen vier Online-Handbüchern wurden keine externen HTML-Links zu Originalquellen gefunden. Quellen stehen als Text, teilweise mit Domain und Abrufdatum. Auch im geprüften NIS2-Memo stehen die Quellen überwiegend als Text.','Linkinventar der Online-Handbücher in EN/DE; NIS2-Ergebnis.','Das stärkste Markenversprechen kostet den Leser zusätzliche Sucharbeit. Eine bibliografische Angabe beweist zudem noch nicht, dass die konkrete Aussage korrekt daraus folgt.','Jede Quelle als anklickbaren Originalbeleg mit genauem Titel, Fundstelle, Dokumentdatum und Abrufdatum aufbereiten. Aussagen mit Quellen-IDs verbinden. Geänderte oder nicht mehr erreichbare Quellen sichtbar behandeln.','Jeder wesentliche Quellenverweis führt zum richtigen Primärdokument und zur nachvollziehbaren Fundstelle. Quellenstichproben werden fachlich gegengeprüft.'),
('P1','F06','Datenschutzaussage und ausgelieferter Cookie widersprechen sich','/privacy behauptet, die Website setze nur einen Kontositzungs-Cookie beim Einloggen. Bereits der anonyme HTTP-Abruf der Startseite lieferte Set-Cookie für __cf_bm. Der Cookie-Wert wurde für den Bericht nicht übernommen.','Anonymer HTTP-Abruf; Antwortheader in der Beweissicherung nur mit geschwärztem Wert.','Die Beschreibung bildet mindestens diesen beobachteten technischen Vorgang nicht vollständig ab. Ob und welche Einwilligung erforderlich ist, wurde hier nicht rechtlich bewertet.','Cookies und Datenflüsse in einem frischen Browser vollständig inventarisieren, Hosting- und Bot-Schutz-Konfiguration zuordnen und die tatsächliche Verarbeitung präzise dokumentieren. Die Formulierung „nur ein Cookie“ erst nach verifizierter Bestandsaufnahme verwenden.','Cookie- und Netzwerk-Inventar passen zur Datenschutzerklärung; jedes beobachtete System ist erklärt. Rechtliche Einordnung separat prüfen lassen.'),
('P1','F07','Antworten und Betriebsname stehen in Memo-URLs','Das NIS2-Memo übergibt country, size, sector und supplier in der Ergebnisadresse. Das Formular und die Datenschutzerklärung nennen ausdrücklich auch den optionalen Betriebsnamen als URL-Inhalt.','NIS2-Browserlauf und /privacy.','URL-Inhalte können in Verlauf, kopierten Links und technischen Logs auftauchen. „Nichts gespeichert“ ist deshalb als pauschale Aussage zu ungenau, selbst wenn die Anwendung keinen Datensatz anlegt.','Betriebsnamen aus URLs entfernen. Für Ergebnisse kurzlebige und angemessen geschützte Referenzen oder eine andere geeignete Zustandsübergabe verwenden. Log-, Cache- und Referrer-Verhalten bewusst prüfen.','Ergebnisadressen enthalten keine freien Betriebs- oder Kontaktnamen. Datenschutztext beschreibt Anwendung und technische Übermittlung getrennt und zutreffend.'),
('P1','F08','Musterantworten wirken zu leicht wie fertige Kundenangaben','Beide Generatoren starten unmittelbar mit einem komplett vorbefüllten erfundenen Betrieb. Das erleichtert den Test, macht aber ungeprüft übernommene Antworten wahrscheinlich. Ein deutlich getrenntes „Muster ausprobieren“ und „Eigenen Betrieb erfassen“ fehlt am Einstieg.','Eigene Durchläufe beider Generatoren bis zur Dokumentübersicht.','Gerade Aussagen über vorhandene Schutzmaßnahmen dürfen nicht versehentlich aus dem Beispiel zum eigenen Nachweis werden.','Zwei Einstiege anbieten: Muster ansehen und eigenen Betrieb erfassen. Im eigenen Lauf Beispielwerte nur als Hilfetext zeigen; bewusste Bestätigung vor Übernahme. Vor Export Übersicht über übernommene, geänderte und offene Antworten.','Ein neuer echter Lauf erzeugt keine behaupteten Unternehmensmerkmale allein aus Musterdefaults. Vor Ausgabe muss der Nutzer die Zusammenfassung prüfen.'),
('P2','F09','Die Startseite erklärt Umfang vor Kundennutzen','Lange Absätze zählen Dokumente, Pflichtfragen, Fundstellen und offene Punkte auf. Für einen Besucher ohne IT-Abteilung ist dadurch die Produktwahl unnötig aufwendig. Beide Hero-Buttons nennen Produktnamen, aber nicht die Situation des Besuchers.','Visuelle und redaktionelle Prüfung der Startseiten EN/DE.','Der Besucher muss erst das Angebot lernen, bevor er seinen eigenen Bedarf erkennt.','Mit zwei Kundensituationen führen: KI im Betrieb regeln oder Sicherheitsfragebogen beantworten. Dokumentdetails dahinter staffeln. Fachbegriffe über konkrete Alltagssituationen erklären.','Im ersten Bildschirm sind Zielgruppe, Ergebnis und nächster Schritt klar. In einem Nutzertest können passende Besucher ihr Produkt ohne Erläuterung zuordnen.'),
('P2','F10','Zu viele gleichartige Abschnitte und Wiederholungen','Die Startseite kombiniert Produkttexte, Preisblöcke, Ablauf, Belegsystem, Mustercarousels, Tools, Memos, Produktvorschau und Benachrichtigung. Produktseiten wiederholen Teile davon ausführlich.','Startseite und Produktseiten, Desktop und Mobil.','Alles bekommt ähnliches Gewicht. Dadurch wirkt die Seite lang, aber nicht abgeschlossen und entschieden.','Startseite auf Auswahl, Ergebnisvorschau, Ablauf und Vertrauensbelege konzentrieren. Ausführliche Dokumentlisten und Quellenmethodik auf klar verlinkte Detailseiten verschieben.','Jeder Abschnitt beantwortet eine eigene Besucherfrage. Die primäre Handlung bleibt eindeutig; keine doppelte Darstellung ohne neue Information.'),
('P2','F11','Dokumente als Dekoration statt lesbare Produktvorschau','Der Hero zeigt einen gedrehten, bewegten Dokumentstapel mit kleinen Beschriftungen. Das vermittelt Materialität, ist aber zum Prüfen der Ergebnisse weniger geeignet als eine ruhige und vergrößerbare Vorschau.','Visuelle Prüfung, ist-desktop.jpg; ausgeliefertes motion.js.','Viel Aufwand steckt in Präsentationseffekten, während der konkrete Nutzen erst weiter unten lesbar wird.','Eine statische Dokumentvorschau mit manuell wählbaren Tabs und echtem Muster-PDF verwenden. Die Bewegung auf kurze, zweckmäßige Übergänge reduzieren. Pause- und Reduced-Motion-Unterstützung beibehalten.','Dokumenttitel, Beispielcharakter und wesentliche Inhalte sind ohne Bewegung lesbar. Alle Dokumente lassen sich bewusst öffnen und vergrößern.'),
('P2','F12','Generator braucht stärkere Orientierung und Rückkehrhilfe','Die Fragebögen zeigen Fragenummer, Bereich, Zurück und Weiter sowie Handbuchverweise als bloße Ziffern. Eine sichtbare Kapitelübersicht, ein verständlicher Speicherstatus und eine belastbare geräteübergreifende Rückkehr wurden im anonymen Test nicht nachgewiesen. Neuladen desselben Testlaufs funktionierte.','Beide Generatoren; Kontoeinstieg; eigene Reload-Tests.','Lange Fragebögen benötigen mehr Sicherheit über Aufwand, Fortschritt und die nächsten Schritte.','Kapitelanzeige mit aktuellem Abschnitt, Speicherhinweis mit tatsächlichem Speicherort, gezieltes Bearbeiten der Antworten und eine abschließende Prüfübersicht ergänzen. Handbuchlinks „Warum wir das fragen“ statt nur „2“ nennen. Dauer erst nach Messung echter Durchläufe nennen.','Besucher sehen, was gespeichert wurde und wie sie zurückkehren. Jede Antwort ist aus der Prüfübersicht erreichbar; Fehler erhalten eine konkrete Erklärung.'),
('P2','F13','Sprachwechsel verliert das Memo-Ergebnis','Das erzeugte NIS2-Memo verlinkt mit „Deutsch“ auf das deutsche Eingabeformular ohne die Ergebnisparameter. Gleiches Muster war bei weiteren Memo-Ergebnisseiten sichtbar.','Eigene erzeugte Memo-Seiten.','Der Sprachwechsel fühlt sich wie ein Neustart an.','Ergebniszustand beim Sprachwechsel sicher erhalten oder deutlich ankündigen, falls ein Neustart notwendig ist.','Die gleichen Antworten und das gleiche Ergebnis bleiben beim Wechsel EN/DE erhalten; die gewählte Sprache bleibt konsistent.'),
('P2','F14','Fehlerseite mit falschem Inhalt','Der bewusst unbekannte Pfad /audit-missing-page-20261101 liefert zwar HTTP 404, sein HTML enthält aber die Startseite mit ihrem Titel und Inhalt.','Eigener technischer Negativtest.','Ein Nutzer erfährt nicht klar, dass sein Link ungültig ist.','Eine echte Fehlerseite mit kurzer Erklärung, Rückweg und Produkt- oder Toolauswahl gestalten.','Status 404 und sichtbare Meldung „Seite nicht gefunden“ stimmen überein. Keine Startseitenkopie als Fehlerinhalt.'),
('P2','F15','Kleine redaktionelle Widersprüche','Die KI-Produktseite verspricht „Access starts immediately“ und später „Answers today … documents tomorrow“, obwohl der Test unmittelbar zur Ausgabe führte. /about spricht von drei Toolkits, während die Startseite zwei verkaufbare und eines in Vorbereitung zeigt. Die Zielgruppengröße schwankt zwischen etwa fünfzig und einigen Hundert Mitarbeitern.','/toolkits/ai-policy, /about und Startseite.','Solche Details summieren sich zum Gefühl einer zusammengebauten, nicht abschließend redigierten Seite.','Leistungsumfang, Status, Zielgruppe und Ablauf zentral definieren und in beiden Sprachen konsistent ausspielen. Verfügbare und geplante Produkte sprachlich trennen.','Kein Widerspruch zu Lieferzeit, Zielgruppe oder Verfügbarkeit zwischen Startseite, Detailseite und Konto.'),
('P2','F16','Barrierefreiheit noch nicht abschließend nachgewiesen','Alle erfassten statischen HTML-Seiten haben eine H1. Memo-Ergebnisse zeigen allerdings eine zweite H1 im Dokument. Der Header beginnt mit normalen Navigationslinks; ein Sprunglink zum Hauptinhalt war in den geprüften Ansichten nicht sichtbar. Kontrast, Fokus und Screenreader-Verhalten wurden nicht vollständig vermessen.','Crawl sowie DOM-Snapshots der Memos.','Die technische Grundlage ist brauchbar, eine vollständige zugängliche Bedienung ist damit noch nicht belegt.','Überschriftenstruktur, Sprunglink, Fokus nach Navigation, Statusmeldungen, Tastaturbedienung und Kontraste gezielt prüfen. Slidersteuerung für Hilfstechnologien verständlich benennen.','Alle Kernabläufe sind allein mit Tastatur ausführbar; Fokus bleibt sichtbar. Die Prüfung gegen definierte Kriterien ist dokumentiert, nicht nur ein automatischer Score.'),
('P2','F17','Öffentlich sichtbare Baukastenkennzeichnung','Die Website enthält ein „Edit with Lovable“-Badge mit Projektlink. Das ist in den Accessibility-Snapshots sichtbar.','Startseite und alle geprüften Seitentypen.','Für eine seriöse, eigenständige Marke wirkt das wie eine nicht abgeschlossene Veröffentlichung.','Badge im vorgesehenen Veröffentlichungsprozess entfernen, soweit der Plattformtarif das erlaubt. Vorschaubanner und interne Arbeitshinweise nur in der Testumgebung anzeigen.','Öffentliche Besucher sehen keine Editoraktion oder interne Projektkennzeichnung.'),
('P2','F18','Dateiformate funktionieren, Inhaltsqualität ist eine eigene Prüfaufgabe','Beide Musterläufe erzeugen Dateilinks. 53 Abrufe wurden strukturell geprüft: 35 PDFs waren parsebar, 18 ZIP-/Office-Dateien hatten lesbare Archive. KI-ZIP enthält 15 Einträge, Sicherheits-ZIP 16. Das beweist weder korrekte Rechtsaussagen noch vollständiges Layout in Word und Excel.','document-checks.json; beide Generatorläufe.','Ein erfolgreicher Download ist ein guter Befund, aber keine inhaltliche Produktabnahme.','Ein Referenzszenario je Zielgruppe fachlich prüfen, abweichende Antworten gezielt testen und alle Dokumente in den Zielanwendungen visuell abnehmen. Versionen und Quellenänderungen nachvollziehbar dokumentieren.','Keine widersprüchlichen Angaben zwischen Antworten und Ausgabe; bearbeitbare Dateien öffnen sauber in Word und Excel. Fachliche und visuelle Abnahme getrennt protokollieren.')]

def finding_html(f):
 p,id,title,obs,src,impact,fix,accept=f
 return f'<article class="finding" id="{id}"><span class="badge {p.lower()}">{p} · {id}</span><h3>{title}</h3><p><b>Beobachtung:</b> {html.escape(obs)}</p><p><b>Auswirkung:</b> {html.escape(impact)}</p><p class="small"><b>Beleg, Abruf 01.11.2026:</b> {html.escape(src)}</p></article>'
scope='''<section><h2>Was geprüft wurde</h2><p>Öffentliche Bestandsaufnahme mit Browserbedienung, HTTP-Abrufen, Linkinventar und struktureller Dateiprüfung. Getestet wurde die am 01.11.2026 ausgelieferte Website. Die Sichtprüfung umfasste Desktop mit 1440 × 1000 Pixeln und Mobil mit 390 × 844 Pixeln sowie die anfängliche schmale Browseransicht.</p><ul><li>60 intern verlinkte URLs: 38 HTML-Seiten und 22 PDF-Endpunkte. Alle antworteten mit HTTP 200. Zusätzlich 10 direkt im HTML referenzierte CSS-/JavaScript-Ressourcen, robots.txt, Sitemap und ein absichtlich ungültiger Pfad.</li><li>Startseiten, Produkte, Online-Handbücher, Tools, Memos, Konto, Über-Seite und Rechtstexte in beiden Sprachen wurden inventarisiert. Dies ist ein Crawl erreichbarer Links, keine Garantie für unbekannte oder geschützte Routen.</li><li>Beide englischen Generatoren wurden mit vorbefüllten fiktiven Beispielen bis zur Dokumentübersicht durchlaufen. Beim KI-Lauf wurden Pflichtfeld und Wiederaufnahme geprüft; beim Sicherheitslauf wurden die Schritte zur Persistenzkontrolle wiederholt neu geladen. Alle Verzweigungen und Eingabekombinationen wurden nicht getestet.</li><li>Alle vier englischen Memos wurden mit je einem Szenario bis zum sichtbaren Ergebnis bedient. Beide lokalen Tools wurden mit gezielten Testfällen geprüft. Kaufbuttons wurden für beide englischen Produkte bedient, ohne eine Zahlung auszuführen.</li><li>53 PDF-, Office- und ZIP-Abrufe aus Musterdateien und den eigenen Generatorläufen wurden strukturell geprüft. Keine visuelle Vollprüfung aller PDF-Seiten und keine fachliche Freigabe sämtlicher Aussagen.</li></ul><div class="note"><b>Kontextgrenze:</b> Der Google-Drive-Konnektor war nicht verbunden. Deshalb konnten „00 START.md“ und die Scutoria-Übersicht im Gedächtnis nicht gelesen werden. Die lokalen Scutoria-Arbeitsregeln wurden gelesen. Die ältere lokale Beschreibung des Shops wurde nicht als Beleg für das aktuelle Hosting übernommen.</div></section>'''
tests=[('Öffentliche EN-/DE-Routen','Bestanden','60 verlinkte Ziele, alle HTTP 200; keine entdeckten toten internen Links.'),('PDF-Muster und Handbuchumfang','Bestanden, strukturell','PDFs parsebar; KI-Handbuch EN/DE 24/26 Seiten, Sicherheits-Handbuch 37/40 Seiten. Keine vollständige Rechtsprüfung.'),('KI-Generator','Bestanden im Musterfall','Bis Dokumentübersicht; leeres Namenspflichtfeld wurde abgewiesen; gleiches Testlauf-URL nach Reload nutzbar.'),('Sicherheitsgenerator','Bestanden im Musterfall','Alle 47 Fragen im vorbefüllten Muster bis zur Ausgabe durchlaufen; Reload-Persistenz geprüft.'),('Dokumentausgabe','Bestanden, strukturell','53 Abrufe ohne HTTP- oder Archivfehler; nicht gleichbedeutend mit Layout- und Inhaltsabnahme.'),('Kaufbuttons','Fehler im Testbrowser','Beide EN-Produkte bleiben ohne Checkout und ohne sichtbare Meldung; Server liefert separat 303 zu Stripe.'),('Ampel','Bestanden in zwei Fällen','Unkritischer Fall grün; Gesundheitsangaben rot; „None of these“ wird bei Auswahl eines Risikos abgewählt.'),('Textprüfer','Bestanden in Stichprobe, Begrenzung sichtbar','Fiktiver markierter Name, E-Mail, Telefon, Passwort und separater Gesundheitsbegriff erkannt. Freier Name ohne Label wird nicht verlässlich erkannt; diese Grenze wird erklärt. Passwortersetzung kann den restlichen Satz mit entfernen.'),('Vier Memo-Generatoren','Bestanden je Szenario','NIS2: kleiner AT-Betrieb ohne Sektor; Kennzeichnung: rein interne Nutzung; Anmeldung: überwiegend vorhandene Kontrollen mit geteiltem Konto; KI-Start: Nutzung einschließlich sensibler Bereiche. Bewertet wurde Ausgabe, nicht die rechtliche Richtigkeit.'),('Bedingte Kennzeichnungsfragen','Bestanden im internen Fall','Memo ließ sich mit Betreiberrolle und rein interner Nutzung erzeugen, ohne unzutreffende Folgefragen beantworten zu müssen.'),('Konto','Teilprüfung bestanden','Ungültige E-Mail wird clientseitig abgewiesen. Kein echter Login-Link versendet.'),('FAQ','Bestanden in Stichprobe','„Who is it for?“ beim Sicherheitsprodukt lässt sich öffnen und zeigt eine konkrete Antwort.'),('Mobile Navigation','Fehler','Hauptlinks versteckt, kein Ersatzmenü; Kontozugang fehlt in der Kopfzeile.'),('Sprachwechsel beim Memo','Fehler','Link führt zum anderssprachigen Eingabeformular und erhält das Ergebnis nicht.'),('404','Teilweise fehlerhaft','HTTP 404 korrekt, sichtbarer HTML-Inhalt entspricht aber der Startseite.'),('Indexierung','Für Vorschau aktiv gesperrt','noindex/nofollow auf allen erfassten HTML-Seiten; robots.txt sperrt Crawling vollständig.'),('Rechtstexte','Redaktionell unfertig','Öffentliche Entwurfsvermerke und Platzhalter. Keine abschließende rechtliche Bewertung.'),('Mail, Rechnung, Zahlung, Lizenzende','Offen','Keine Zustellung, Zahlung, Rechnung, Verlängerung oder echte Kundenkontoaktion ausgeführt.'),('Sicherheit, Datenschutz, Barrierefreiheit','Begrenzte Prüfung','Header und auffällige Datenflüsse betrachtet. Kein Penetrationstest, kein vollständiges WCAG-Audit, keine Backend- oder Berechtigungsprüfung.'),('Ladeleistung','Nicht abschließend ermittelbar','Keine belastbare Lighthouse-, Core-Web-Vitals- oder Felddatenmessung. Einzelne HTTP-Laufzeiten sind keine Nutzer-Performancewerte.')]
testtable='<div class="scroll"><table><tr><th>Prüfung</th><th>Ergebnis</th><th>Beleg und Grenze, 01.11.2026</th></tr>'+''.join('<tr>'+''.join('<td>'+html.escape(c)+'</td>' for c in row)+'</tr>' for row in tests)+'</table></div>'
analysis='<section><h2>Dein Eindruck trifft einen echten Punkt</h2><p class="intro">Das Farbsystem ist bereits überzeugend. Der unfertige Eindruck entsteht vor allem durch einen unklaren Veröffentlichungsstatus, fehlende Führung und nicht geschlossene Kundenwege. Die Produktidee und die Dokumentausgabe sind weiter als die öffentliche Verpackung.</p><p><b>Empfehlung:</b> Navy, Blau und die nüchterne Grundhaltung behalten. Zuerst Kaufweg, Status, mobile Navigation und verlässliche Aussagen schließen. Danach die Startseite klarer gliedern und die Dokumente lesbar präsentieren. Zusätzliche Effekte sind dafür nicht nötig.</p></section>'+scope+'<section><h2>Was schon gut ist</h2><ul><li><b>Eigenständige Farbwelt:</b> Dunkles Navy, klares Blau, helle Schrift und zurückhaltende Sekundärfarben passen zur sachlichen Ausrichtung.</li><li><b>Ein greifbares Produkt:</b> Es gibt durchlaufbare Fragebögen, Muster-PDFs, umfangreiche Handbücher und bearbeitbare Ausgabeformate.</li><li><b>Gute Transparenzidee:</b> Fakt, Auslegung, Unsicher und Lücke sind als Methode stärker als pauschale Sicherheitsversprechen. Die Belege müssen allerdings leichter prüfbar werden.</li><li><b>Sprachen sind breit vorhanden:</b> Die wesentlichen öffentlichen Seiten haben englische und deutsche Fassungen; Canonical- und hreflang-Angaben sind im HTML vorhanden.</li><li><b>Grundlegende Schutzheader:</b> Die geprüfte Startseitenantwort enthält unter anderem HSTS, CSP, nosniff und eingeschränkte Geräteberechtigungen. Das ist ein positiver Grundbefund, kein Sicherheitszertifikat.</li><li><b>Bedienbare kleine Helfer:</b> Die lokalen Tools liefern in den getesteten Fällen nachvollziehbare Ergebnisse und erklären ihre Grenzen.</li></ul></section><section><h2>Warum es halb fertig wirkt</h2><p>Der erste Bildschirm liefert ein starkes Motto, aber erklärt die Kundenaufgabe erst in einem langen Absatz. Danach folgen viele ähnlich gewichtete Textblöcke. Bewegte Dokumente vermitteln Wertigkeit, bleiben als Lesebeispiel aber klein. Auf Mobil fehlt die globale Navigation. Zusätzlich stehen Vorschau, Kaufversprechen, freie Generatoren und unfertige Pflichttexte nebeneinander. Diese Widersprüche prägen den Eindruck stärker als Farbe oder Schrift.</p><div class="compare"><div><h3>Aktuelle Desktopansicht</h3><img src="ist-desktop.jpg" alt="Aktuelle Startseite auf Desktop"></div><div><h3>Aktuelle Mobilansicht</h3><img src="ist-mobil.jpg" alt="Aktuelle deutsche Startseite auf schmalem Bildschirm" style="max-width:300px"></div></div></section><section><h2>Testprotokoll</h2>'+testtable+'</section><section><h2>Befunde mit Belegen</h2><p>Prioritäten sind fachliche Einschätzungen dieses Audits: P0 vor Verkaufsfreigabe schließen, P1 hohe Wirkung, P2 strukturelle und gestalterische Verbesserung. Ein beobachteter Fehler und eine vermutete Ursache werden getrennt ausgewiesen.</p>'+''.join(map(finding_html,findings))+'</section>'
inventory='<section><h2>Vollständiges URL-Inventar des Crawls</h2><p>Abrufdatum für alle Einträge: 01.11.2026. Erzeugte Testlauf-URLs stehen separat in der Beweissicherung und werden hier nicht als öffentliche Seitenliste vermischt.</p><div class="scroll"><table><tr><th>Status</th><th>Typ</th><th>Adresse</th></tr>'+''.join(f'<tr><td>{p.get("status","Fehler")}</td><td>{"HTML" if "title" in p else "PDF"}</td><td><a href="{html.escape(p["url"])}">{html.escape(p["url"])}</a></td></tr>' for p in d['pages'])+'</table></div></section>'
sources='''<section><h2>Quellen und Nachprüfbarkeit</h2><p>Primärmaterial ist die ausgelieferte <a href="https://scutoria.com/">Website</a>, insbesondere <a href="https://scutoria.com/toolkits/ai-policy">KI-Produktseite</a>, <a href="https://scutoria.com/toolkits/security-evidence">Sicherheitsproduktseite</a>, <a href="https://scutoria.com/privacy">Datenschutzerklärung</a>, <a href="https://scutoria.com/about">Über-Seite</a>, <a href="https://scutoria.com/robots.txt">robots.txt</a> und <a href="https://scutoria.com/sitemap.xml">Sitemap</a>. Abruf aller Belege: 01.11.2026.</p><p>Für die technische Einordnung: <a href="https://developers.google.com/search/docs/crawling-indexing/block-indexing">Google Search Central zu noindex</a> und <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Content-Security-Policy/form-action">MDN zur CSP-Direktive form-action</a>, abgerufen 01.11.2026. MDN beschreibt ausdrücklich Unterschiede zwischen Browsern bei Weiterleitungen nach Formularversand. Deshalb wird die CSP hier als Hypothese, nicht als bewiesene Ursache genannt.</p><p>Rohbelege: <a href="crawl-results.json">Crawl</a>, <a href="document-checks.json">Dateiprüfungen</a>, <a href="security-walkthrough.json">Sicherheitsfragebogen</a>, <a href="memo-results.json">Memo-Testfälle</a>. Preise, Fragen- und Seitenzahlen sind Bestandsangaben aus diesen Abrufen, keine neuen Festlegungen oder Zusagen. Fachliche Rechtsaussagen der Produkte wurden nicht vollständig gegen die Originalquellen freigegeben.</p></section>'''
page('Analysebericht','Gestaltung, Inhalte, Kundenwege und technische Bestandsaufnahme. Beobachtungen mit Belegen und klaren Testgrenzen.',analysis+inventory+sources,'analysebericht.html')
plan='''<section><h2>Was ich ändern würde</h2><p class="intro">Die Marke braucht eine fertig geführte Produkterfahrung. Behalte die Farben und mache die Kundenaufgabe, das Ergebnis und den nächsten Schritt deutlicher.</p><p>Meine bevorzugte Richtung ist <b>Variante A</b> als visuelle Grundlage, ergänzt um die Bedarfsauswahl aus <b>Variante B</b>. Die helle Dokumentenfläche aus <b>Variante C</b> eignet sich besonders für Handbuch, Muster und Generatorausgabe.</p></section><section><h2>Umsetzung in sinnvoller Reihenfolge</h2><div class="scroll"><table><tr><th>Etappe</th><th>Ergebnis</th><th>Abhängigkeit und Abnahme</th></tr><tr><td>Verkaufsbereitschaft</td><td>Kaufnavigation, Statuslogik, Datenschutzaussagen und reale Datenflüsse schließen.</td><td>F01, F02, F06, F07. Echte Zahlung und Zustellung erst im geeigneten Testmodus prüfen; Recht und Live-Freigabe durch Stefan.</td></tr><tr><td>Orientierung</td><td>Mobile Navigation, klare Produktauswahl, lesbare Dokumentvorschau und konsistente Texte.</td><td>F03, F08 bis F12, F15, F17. Reale Nutzer sollen Aufgabe und Produkt selbst zuordnen können.</td></tr><tr><td>Nachvollziehbarkeit</td><td>Originalquellen anklickbar, Ausgabe geprüft, Versionen und offene Punkte verständlich.</td><td>F05, F18. Fachliche Stichproben separat dokumentieren.</td></tr><tr><td>Veröffentlichung</td><td>Indexierung gezielt freigeben, Fehlerseiten und Sprachwechsel schließen, Browser- und Zugänglichkeitsprüfung.</td><td>F04, F13, F14, F16. Erst nach bewusster Entscheidung über den öffentlichen Betriebsstatus.</td></tr></table></div><p>Es werden keine Stunden- oder Umsatzschätzungen angegeben: Ohne Codeprüfung, Anbieterzugänge und Nutzungsdaten wären diese nicht belastbar.</p></section><section><h2>Neue Informationsarchitektur</h2><ul><li><b>Startseite:</b> Kundenaufgabe, konkretes Ergebnis, Produktauswahl, lesbares Muster, Ablauf und wenige prüfbare Vertrauensbelege.</li><li><b>Produktseite:</b> Für wen, Ergebnisbeispiel, enthaltene Dokumente, Eingabeaufwand, Leistungsgrenzen, Lizenz und FAQ. Muster- und Eigenbetriebseinstieg klar trennen.</li><li><b>Kostenlose Tools:</b> Die beiden Browserprüfer und die vier Memo-Generatoren als getrennte Gruppen mit verständlicher Erklärung der Datenverarbeitung.</li><li><b>Handbuch:</b> Such- oder Inhaltsnavigation, feste Kapitelanker, kurze Zusammenfassungen und Quellen direkt am Absatz.</li><li><b>Konto:</b> Lizenz, eigene Läufe, Dateien, Versionen und klare Wiederaufnahme. Dieser Bereich wurde mangels echtem Login nicht vollständig geprüft.</li></ul></section><section><h2>Textvorschlag für den ersten Bildschirm</h2><p>Entwurf, noch nicht für die Veröffentlichung freigegeben:</p><div class="compare"><div><span class="badge">English first</span><h3>Clear rules.<br>Evidence you can show.</h3><p>Turn your answers into an AI policy or a security evidence pack. With editable documents, dated sources and visible open points.</p><p><b>Find your toolkit</b> · Explore a sample</p></div><div><span class="badge">Deutsch</span><h3>Klare Regeln.<br>Vorzeigbare Nachweise.</h3><p>Aus Ihren Antworten entstehen eine KI-Richtlinie oder ein Sicherheitsnachweis. Mit bearbeitbaren Dokumenten, datierten Quellen und sichtbaren offenen Punkten.</p><p><b>Passendes Toolkit finden</b> · Muster ansehen</p></div></div><p>Das bestehende Motto „Sourced. Dated. Ready to show.“ kann als Markenleitsatz erhalten bleiben. Die größere Überschrift sollte dem Erstbesucher stärker sagen, was er erhält.</p></section><section><h2>Visuelles System</h2><div class="swatches"><div class="swatch" style="background:#0b1120">Navy #0B1120</div><div class="swatch" style="background:#2f6be6">Blau #2F6BE6</div><div class="swatch" style="background:#4f8cff">Akzent #4F8CFF</div><div class="swatch" style="background:#a1adc4;color:#14243e">Sekundär #A1ADC4</div><div class="swatch" style="background:#e9eef8;color:#14243e">Text #E9EEF8</div></div><p>Die Kernfarben stammen aus den berechneten Styles der bestehenden Seite, abgerufen 01.11.2026. Helle Dokumentflächen ergänzen die Marke, ohne sie umzubauen. In den Prototypen stehen Bahnschrift bzw. Systemschriften für Überschriften und Segoe UI für Lesetext; eine Serifenschrift erscheint nur im Dokumentbeispiel. Es werden keine externen Fonts geladen.</p><ul><li>Weniger Großbuchstaben und mehr deutliche Satzüberschriften.</li><li>Gleichartige Buttons mit klarer Rangfolge; gleichartige Informationen in vergleichbaren Produktkarten.</li><li>Dokumente frontal und lesbar statt als ständig bewegtes Objekt.</li><li>Abschnittsabstände nach Bedeutung staffeln. Nutzen und Muster enger zusammenführen.</li><li>Keine erfundenen Kundenlogos, Bewertungen, Erfolgszahlen oder angeblichen Zertifizierungen ergänzen.</li></ul></section>'''
fixes='<section><h2>Konkrete Änderungen und Abnahmekriterien</h2>'+''.join(f'<article class="finding"><span class="badge {f[0].lower()}">{f[0]} · {f[1]}</span><h3>{f[2]}</h3><p><b>So ändern:</b> {html.escape(f[6])}</p><p><b>Abnahme:</b> {html.escape(f[7])}</p><p class="small"><a href="analysebericht.html#{f[1]}">Beobachtung und Beleg im Analysebericht</a></p></article>' for f in findings)+'</section>'
variants='''<section><h2>Drei Designrichtungen</h2><div class="grid">'''+''.join(f'<article class="card"><a href="variante-{v}.html?lang=de"><img src="design-{v}-desktop.jpg" alt="Designvariante {v.upper()}"></a><h3>{name}</h3><p>{desc}</p><a class="btn" href="variante-{v}.html?lang=de">Deutsch öffnen</a><a href="variante-{v}.html">English</a></article>' for v,name,desc in [('a','A · Klarer Produktauftritt','Meine Empfehlung als Basis. Bestehendes dunkles Farbsystem, konkreter Nutzen, ruhige Dokumentvorschau und zwei vergleichbare Produktkarten. Geringste visuelle Umstellung.'),('b','B · Geführte Bedarfsauswahl','Für Besucher, die die Produktnamen noch nicht kennen. Zwei Situationen führen zum passenden Dokumentensatz. Die Auswahl ist im Prototyp bedienbar.'),('c','C · Heller Dokumententisch','Navy-Kopfzeile und blaue Marke bleiben. Helle Inhaltsflächen machen längere Texte und Dokumente ruhiger lesbar. Größere Änderung des Gesamteindrucks.')])+'</div><p>Alle drei Prototypen haben Sprachwechsel, mobile Navigation, Dokument-Tabs und Produktdetails. Sie sind responsive HTML-Dateien, keine veröffentlichten Shopänderungen. Dokumentvorschauen sind illustrative Entwürfe. Preise entsprechen dem sichtbaren Bestand und werden nicht neu festgelegt.</p></section>'
page('Verbesserungsbericht','Konkrete Änderungen, Prioritäten, Abnahmekriterien und drei bedienbare Designvarianten.',plan+variants+fixes+sources,'verbesserungsbericht.html')
index='''<section><h2>Farben behalten. Kundenwege fertig machen.</h2><p class="intro">Dein Eindruck ist nachvollziehbar: Der Auftritt wirkt an entscheidenden Stellen noch wie eine Vorschau. Gleichzeitig funktionieren die Dokumentgeneratoren und viele Inhalte bereits. Die größte Verbesserung kommt durch einen klaren Betriebsstatus, einen verlässlichen Kaufweg und eine einfachere Produktauswahl.</p><a class="btn" href="analysebericht.html">Analysebericht lesen</a><a class="btn" href="verbesserungsbericht.html">Verbesserungsbericht lesen</a></section><section><h2>Die wichtigsten Befunde</h2><ul><li><b>Kaufweg:</b> Beide getesteten Kaufbuttons öffnen im In-App-Browser keinen Checkout, obwohl der Server Stripe-Weiterleitungen erzeugt.</li><li><b>Status und Vertrauen:</b> Vorschau, Kaufversprechen, freie Generatoren und unfertige Datenschutzhinweise stehen nebeneinander.</li><li><b>Mobil:</b> Die Hauptnavigation verschwindet ohne Ersatzmenü.</li><li><b>Auffindbarkeit:</b> Alle erfassten HTML-Seiten sind mit noindex/nofollow versehen; robots.txt sperrt Crawling.</li><li><b>Substanz:</b> Beide Generatoren erreichen mit den fiktiven Beispielen die Ausgabe; alle vier Memos lieferten je ein Ergebnis. Die geprüften Dateien sind strukturell lesbar.</li></ul><p>Alle Feststellungen beziehen sich auf die Abrufe und Tests vom 01.11.2026. Der vollständige Bericht trennt bestätigte Beobachtungen, Ursachenhypothesen und offene Prüfungen.</p></section>'''+variants+'''<section><h2>Meine Empfehlung</h2><p><b>Variante A als Grundlage, Bedarfsauswahl aus B ergänzen.</b> So bleibt die gute Markenwelt erhalten. Für Handbücher und Dokumente würde ich die hellen Leseflächen aus C einsetzen. Das ist ein Gestaltungsvorschlag zur Entscheidung, keine bereits beschlossene Umstellung.</p><p>Öffne die HTML-Dateien im Browser. Sprachwechsel, Vorschau-Tabs, Produktauswahl in B, Detaildialoge und Mobilmenü sind bedienbar. Es gibt keine Kaufabwicklung im Prototyp.</p></section>'''+scope
page('Scutoria: Analyse & Design','Ein prüfbarer Bericht über den aktuellen Stand und konkrete Entwürfe für einen fertigen Produktauftritt.',index,'index.html')
# Remove transient cookie secrets from persistent response headers.
for group in ['pages','assets','technical']:
 for p in d[group]:
  for k in list(p.get('headers',{})):
   if k.lower()=='set-cookie':
    import re
    p['headers'][k]=re.sub(r'(^|,\s*)([^=;, ]+)=([^;]+)',r'\1\2=[WERT GESCHWAERZT]',p['headers'][k])
(r/'crawl-results.json').write_text(json.dumps(d,ensure_ascii=False,indent=2),encoding='utf8')
(r/'LESEN.txt').write_text('Scutoria Website-Audit, 01.11.2026\n\nÖffne index.html im Browser.\nAnalysebericht: analysebericht.html\nVerbesserungsbericht: verbesserungsbericht.html\nDesigns: variante-a.html, variante-b.html, variante-c.html\n\nAlle Berichte sind deutsch. Designs starten englisch und lassen sich auf Deutsch umschalten. Die Dateien funktionieren lokal ohne Installation. Keine Live-Änderung vorgenommen.\n\nRohbelege enthalten technische Bestandsdaten und ausschließlich eigene fiktive Testläufe. Keine echte Zahlung oder E-Mail-Zustellung ausgeführt.\n',encoding='utf8')
print('Übersicht, Analysebericht und Verbesserungsbericht erstellt; Cookie-Werte geschwärzt.')
